def abstract_states(grid_world):
    """
    This function groups states into abstract states based on their distance to the goal.

    Args:
        grid_world (dict): A dictionary containing the grid world information.

    Returns:
        list[list[int]]: A 2D list where each sublist contains states that are at the same distance from the goal.
    """

    # Get the grid and goal position
    grid = grid_world['grid']
    goal = grid_world['goal']

    # Find the coordinates of the goal in the grid
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == goal:
                goal_coords = (i, j)

    # Initialize a dictionary to store distances from each state to the goal
    distances = {}

    # Perform BFS to calculate distances from each state to the goal
    queue = [(goal_coords, 0)]
    visited = set()

    while queue:
        (x, y), dist = queue.pop(0)

        if (x, y) not in visited:
            visited.add((x, y))

            # Get the value of the current cell
            for i, row in enumerate(grid):
                for j, cell in enumerate(row):
                    if (i, j) == (x, y):
                        distances[cell] = dist

            # Add neighbors to the queue
            directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                    is_valid = False
                    for i, row in enumerate(grid):
                        for j, cell in enumerate(row):
                            if (i, j) == (nx, ny) and not isinstance(cell, str):
                                is_valid = True
                    if is_valid:
                        queue.append(((nx, ny), dist + 1))

    # Group states into abstract states based on their distances to the goal
    abstract_states = {}

    for state, distance in distances.items():
        if distance not in abstract_states:
            abstract_states[distance] = [state]
        else:
            abstract_states[distance].append(state)

    return list(abstract_states.values())

