def group_states(grid_world):
    grid = grid_world["grid"]
    goal = grid_world["goal"]
    start = grid_world["start"]

    # Find the shortest path to the goal using BFS
    queue = [(start, [start])]
    visited = set()
    while queue:
        (node, path) = queue.pop(0)
        if node not in visited:
            if node == goal:
                return [[state for state in path]]
            visited.add(node)
            # Get adjacent states
            x = None
            y = None
            for i, row in enumerate(grid):
                for j, val in enumerate(row):
                    if val == node:
                        x = i
                        y = j
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                    next_state = grid[nx][ny]
                    if next_state != "X" and next_state not in path:
                        queue.append((next_state, path + [next_state]))
            # If no adjacent states are reachable, group the current state with the goal
            if node != start and len(path) == 1:
                return [[state for state in [start, goal]]]

    # If no path is found, group all states together
    states = []
    for row in grid:
        for cell in row:
            if cell != "X":
                states.append(cell)
    return [states]


